function ring(pts) {
  var a = 0, cx = 0, cy = 0;
  for (var i = 0; i < pts.length; i++) {
    var p = pts[i], q = pts[(i + 1) % pts.length];
    var c = p[0] * q[1] - q[0] * p[1];
    a += c; cx += (p[0] + q[0]) * c; cy += (p[1] + q[1]) * c;
  }
  return { a: a / 2, cx: cx, cy: cy };
}
function widget(project, params, ctx) {
  var items = [];
  var zh = ctx.language !== 'en';
  for (var s of project.spaces) {
    if (!s.shape || !s.shape.length) continue;
    var area = 0, best = null;
    for (var part of s.shape) {
      var r = ring(part.outer);
      var pa = Math.abs(r.a);
      for (var h of part.holes || []) pa -= Math.abs(ring(h).a);
      area += pa;
      if (!best || Math.abs(r.a) > Math.abs(best.a)) best = r;
    }
    if (!best || best.a === 0) continue;
    var at = [best.cx / (6 * best.a), best.cy / (6 * best.a)];
    var m2 = (area / 1e6).toFixed(params.decimals);
    var text = params.showName ? s.name + ' ' + m2 + ' m²' : m2 + ' m²';
    items.push({ type: 'label', at: at, text: text, level: s.level });
  }
  return items;
}

function widget(project, params, ctx) {
  var items = [];
  var key = params.match || '庭院';
  for (var s of project.spaces) {
    if (s.name.indexOf(key) < 0 || !s.shape) continue;
    for (var part of s.shape) {
      var o = part.outer;
      if (!o || o.length < 3 || o.length > 500) continue;
      var a = 0;
      for (var i = 0; i < o.length; i++) {
        var p = o[i], q = o[(i + 1) % o.length];
        a += p[0] * q[1] - q[0] * p[1];
      }
      var m2 = Math.abs(a) / 2 / 1e6;
      var count = Math.max(20, Math.min(4000, Math.round(m2 * params.density)));
      items.push({
        type: 'particles', outline: o, level: s.level,
        from: 0, to: params.height,
        count: count, fall: params.fall, drift: params.drift,
        wind: [params.wind, 0.2], size: params.size,
        shape: 'flake', tone: 'leaf'
      });
    }
  }
  if (params.sky !== 'none') items.push({ type: 'sky', mood: params.sky });
  return items;
}
